  if (tutoria.estado.toLowerCase() === "completada" || tutoria.estado.toLowerCase() === "activa") estadoEmoji = "✅";

  return `🆔 ${tutoria.id_tutoria} | 📘 ${tutoria.materia} (${estadoEmoji} Estado: ${tutoria.estado})`;
}).join("\n");

